mapper.select:
/* SQL ID : QbnkCtgrDAO.profQbnkCtgrList 설 명 : 교수문제은행분류목록조회 */ WITH PROF_USER AS ( -- 기준 과목의 담당교수(PROF) 단건 SELECT USER_ID FROM ( SELECT USER_ID, ROW_NUMBER() OVER (ORDER BY SBJCT_ADM_SEQNO ASC) AS RNUM FROM TB_LMS_SBJCT_ADM WHERE SBJCT_ADM_TYCD = 'PROF' AND SBJCT_ID = #{sbjctId} ) WHERE RNUM = 1 ), PROF_SBJCT AS ( -- 그 교수가 PROF로 등록된 모든 과목 SELECT SBJCT.SBJCT_ID FROM TB_LMS_SBJCT SBJCT JOIN TB_LMS_SBJCT_ADM ADM ON ADM.SBJCT_ID = SBJCT.SBJCT_ID AND ADM.SBJCT_ADM_TYCD = 'PROF' JOIN PROF_USER PU ON PU.USER_ID = ADM.USER_ID WHERE SBJCT.DELYN = 'N' AND SBJCT.USEYN = 'Y' ) SELECT CTGR.QBNK_CTGR_ID, CTGR.CTGRNM FROM TB_LMS_QBNK_CTGR CTGR JOIN PROF_SBJCT PS ON PS.SBJCT_ID = CTGR.SBJCT_ID WHERE CTGR.DELYN = 'N'
AND CTGR.UP_QBNK_CTGR_ID = #{upQbnkCtgrId}
AND CTGR.UP_QBNK_CTGR_ID IS NULL
ORDER BY CTGR.CTGR_SEQNO

/* SQL ID : QbnkCtgrDAO.profQbnkCtgrAllList 설 명 : 교수문제은행분류전체목록조회 */
WITH PROF_USER AS ( -- 기준 과목의 담당교수(PROF) 단건 SELECT USER_ID FROM ( SELECT USER_ID, ROW_NUMBER() OVER (ORDER BY SBJCT_ADM_SEQNO ASC) AS RNUM FROM TB_LMS_SBJCT_ADM WHERE SBJCT_ADM_TYCD = 'PROF' AND SBJCT_ID = #{searchKey} ) WHERE RNUM = 1 ), PROF_SBJCT AS ( -- 그 교수가 PROF로 등록된 모든 과목 SELECT SBJCT.SBJCT_ID, PU.USER_ID FROM TB_LMS_SBJCT SBJCT JOIN TB_LMS_SBJCT_ADM ADM ON ADM.SBJCT_ID = SBJCT.SBJCT_ID AND ADM.SBJCT_ADM_TYCD = 'PROF' JOIN PROF_USER PU ON PU.USER_ID = ADM.USER_ID WHERE SBJCT.DELYN = 'N' AND SBJCT.USEYN = 'Y' ) SELECT A.* , ROW_NUMBER() OVER (ORDER BY A.GRP_QBNK_CTGR_ID DESC, CASE WHEN A.UP_QBNK_CTGR_ID IS NULL THEN 0 ELSE 1 END, A.CTGR_SEQNO) AS LINE_NO , COUNT(A.QBNK_CTGR_ID) OVER() AS TOTAL_CNT FROM ( SELECT CTGR.QBNK_CTGR_ID , CASE WHEN CTGR.UP_QBNK_CTGR_ID IS NULL THEN CTGR.CTGRNM ELSE PARENT.CTGRNM END AS UP_QBNK_CTGRNM , CASE WHEN CTGR.UP_QBNK_CTGR_ID IS NULL THEN '-' ELSE CTGR.CTGRNM END AS CTGRNM , SBJCT.SBJCTNM , SBJCT.DVCLAS_NO , USR.USERNM , CTGR.CTGR_SEQNO , CTGR.UP_QBNK_CTGR_ID , NVL(CTGR.UP_QBNK_CTGR_ID, CTGR.QBNK_CTGR_ID) AS GRP_QBNK_CTGR_ID -- 상위/하위 분류를 묶어서 정렬하기 위한 그룹핑 키 FROM TB_LMS_QBNK_CTGR CTGR JOIN TB_LMS_SBJCT SBJCT ON CTGR.SBJCT_ID = SBJCT.SBJCT_ID AND SBJCT.USEYN = 'Y' AND SBJCT.DELYN = 'N' JOIN PROF_SBJCT ADM ON ADM.SBJCT_ID = SBJCT.SBJCT_ID JOIN TB_LMS_USER USR ON USR.USER_ID = ADM.USER_ID AND USR.USER_ID_STSCD = 'APRV_CMPTN' LEFT JOIN TB_LMS_QBNK_CTGR PARENT -- 상위 카테고리명 조회용 자기조인 ON PARENT.QBNK_CTGR_ID = CTGR.UP_QBNK_CTGR_ID WHERE CTGR.DELYN = 'N'
AND ( CTGR.UP_QBNK_CTGR_ID = #{upQbnkCtgrId} OR CTGR.QBNK_CTGR_ID = #{upQbnkCtgrId} )
AND CTGR.QBNK_CTGR_ID = #{qbnkCtgrId}
AND CTGR.SBJCT_ID = #{sbjctId}
AND CTGR.USER_ID = #{userId}
AND ( LOWER(CTGR.CTGRNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(SBJCT.SBJCTNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(USR.USERNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) )
) A

/* SQL ID : QbnkCtgrDAO.qbnkNextCtgrSeqnoSelect 설 명 : 문제은행다음분류순번조회 */ SELECT NVL(MAX(CTGR_SEQNO), 0) + 1 FROM TB_LMS_QBNK_CTGR WHERE DELYN = 'N'
AND USER_ID = #{userId}
AND UP_QBNK_CTGR_ID = #{upQbnkCtgrId}
AND UP_QBNK_CTGR_ID IS NULL

mapper.delete:
		/*
             SQL ID : QbnkCtgrDAO.qbnkCtgrDelete
             설  명 : 문제은행분류삭제
         */
        UPDATE TB_LMS_QBNK_CTGR SET
        	  DELYN = 'Y'
        	, MDFR_ID = #{mdfrId}
        	, MOD_DTTM = FN_DTTM()
         WHERE QBNK_CTGR_ID = #{qbnkCtgrId}
